<script setup>
defineProps({ job: Object, provider: String, cli: String, endpoint: String, model: String, apiKey: String, running: Boolean, error: String });
const emit = defineEmits(["update:provider", "update:cli", "update:endpoint", "update:model", "update:apiKey", "back", "analyze"]);
</script>
<template><section class="screen"><header class="screen-heading"><div><p class="eyebrow">ETAPA 2 DE 4 · VAGA</p><h1>Defina o alvo da candidatura.</h1><p>Cole a descrição completa. A URL é opcional; o texto é a fonte confiável para análise.</p></div></header><q-input v-model.trim="job.url" outlined type="url" label="URL da vaga (opcional)"/><q-input v-model="job.description" outlined type="textarea" autogrow class="job-input" label="Descrição da vaga" hint="Inclua requisitos, responsabilidades e critérios obrigatórios."/><q-expansion-item icon="settings" label="Configurar bridge local (avançado)" header-class="disclosure"><div class="advanced"><q-select :model-value="provider" outlined emit-value map-options label="Integração" :options="[{ label: 'Fake local', value: 'fake' }, { label: 'CLI local', value: 'cli' }, { label: 'API própria (BYOK)', value: 'byok' }]" @update:model-value="emit('update:provider', $event)"/><q-select v-if="provider === 'cli'" :model-value="cli" outlined emit-value map-options label="CLI" :options="[{ label: 'Codex CLI', value: 'codex' }, { label: 'Claude CLI', value: 'claude' }]" @update:model-value="emit('update:cli', $event)"/><template v-if="provider === 'byok'"><q-input :model-value="endpoint" outlined label="Endpoint HTTPS" @update:model-value="emit('update:endpoint', $event)"/><q-input :model-value="model" outlined label="Modelo" @update:model-value="emit('update:model', $event)"/><q-input :model-value="apiKey" outlined type="password" label="Chave de API" @update:model-value="emit('update:apiKey', $event)"/></template></div></q-expansion-item><q-banner v-if="error" class="notice error" role="alert">{{ error }}</q-banner><footer class="screen-actions"><q-btn flat no-caps label="Voltar ao perfil" @click="emit('back')"/><q-btn unelevated no-caps color="primary" :loading="running" label="Analisar compatibilidade" icon-right="arrow_forward" @click="emit('analyze')"/></footer></section></template>
